#include "auction_analysis_page.hpp"
#include "auction_analysis_model.hpp"
#include <QtWidgets>
namespace {
class Page:public QWidget {
public:
AuctionAnalysisSnapshots provider;QJsonArray snapshots,matched,items;QJsonObject captured,result;QMap<QString,QComboBox*> filters;QLineEdit* search;QListWidget *list,*data;QComboBox* section;QPlainTextEdit* reader;QLabel *status,*summary,*sourceNote;std::function<void()> requestReload;QStackedWidget* stack;int listPage=0,dataPage=0,readerBack=1;bool loading=false;QPushButton *prev,*next;
Page(QWidget*p,AuctionAnalysisSnapshots s,std::function<void()> reload):QWidget(p),provider(s),requestReload(reload){auto outer=new QVBoxLayout(this);sourceNote=new QLabel(this);sourceNote->setObjectName("auctionAnalysisSourceNote");sourceNote->setWordWrap(true);sourceNote->setMaximumHeight(110);sourceNote->setTextFormat(Qt::PlainText);outer->addWidget(sourceNote);stack=new QStackedWidget(this);outer->addWidget(stack,1);status=new QLabel(this);status->setWordWrap(true);status->setTextFormat(Qt::PlainText);outer->addWidget(status);auto main=new QWidget(stack);stack->addWidget(main);auto l=new QVBoxLayout(main);l->addWidget(new QLabel("集合竞价形态 / 历史观察",main));search=new QLineEdit(main);search->setObjectName("auctionAnalysisSearch");search->setPlaceholderText("搜索完整证券身份、快照或来源");l->addWidget(search);auto f=new QHBoxLayout;l->addLayout(f);for(auto key:{"instrumentId","date","phase"}){auto c=new QComboBox(main);filters[key]=c;f->addWidget(c);connect(c,qOverload<int>(&QComboBox::currentIndexChanged),this,[=](int){if(!loading){listPage=0;render();}});}list=new QListWidget(main);list->setObjectName("auctionAnalysisSnapshots");l->addWidget(list,1);auto actions=new QHBoxLayout;l->addLayout(actions);auto button=[&](QBoxLayout* target,QString text,std::function<void()> fn){auto b=new QPushButton(text,this);target->addWidget(b);connect(b,&QPushButton::clicked,this,[=]{guard(fn);});return b;};button(actions,"上一页",[=]{if(listPage>0)--listPage;render();});button(actions,"下一页",[=]{if((listPage+1)*20<matched.size())++listPage;render();});button(actions,"分析所选本机快照",[=]{if(!list->currentItem())throw std::runtime_error("先选真实现有快照");captured=list->currentItem()->data(Qt::UserRole).toJsonObject();result=auctionAnalysis::analyze(captured);summary->setText("证券："+captured.value("instrumentId").toString()+" · 日期："+field(captured,"date")+" · 阶段："+field(captured,"phase")+"\n截至："+captured.value("input").toObject().value("asOf").toString()+"\n状态："+result.value("patternStatus").toString()+" · "+result.value("reason").toString()+"\n历史可用日数："+QString::number(result.value("historyCount").toInt())+"（不是历史存在总数）");dataPage=0;renderData();stack->setCurrentIndex(1);});button(actions,"重读本机竞价归档",[=]{if(requestReload)requestReload();else refresh();});button(actions,"来源读取完整说明",[=]{reader->setPlainText(property("sourceEvidence").toString());readerBack=0;stack->setCurrentIndex(2);});
auto detail=new QWidget(stack);stack->addWidget(detail);auto d=new QVBoxLayout(detail);button(d,"返回快照筛选",[=]{stack->setCurrentIndex(0);});summary=new QLabel(detail);summary->setWordWrap(true);summary->setTextFormat(Qt::PlainText);d->addWidget(summary);section=new QComboBox(detail);section->addItem("完整原点审计","pointAudit");section->addItem("历史资格/日期审计","historyAudit");section->addItem("八形态规则与理由","rules");section->addItem("本次形态与证据","patterns");d->addWidget(section);data=new QListWidget(detail);data->setObjectName("auctionAnalysisRows");d->addWidget(data,1);auto da=new QHBoxLayout;d->addLayout(da);prev=button(da,"原点/历史上一页",[=]{if(dataPage>0)--dataPage;renderData();});next=button(da,"原点/历史下一页",[=]{if((dataPage+1)*20<items.size())++dataPage;renderData();});button(da,"阅读所选完整记录",[=]{if(!data->currentItem())throw std::runtime_error("先选原点/历史/规则");readerBack=1;reader->setPlainText(QString::fromUtf8(QJsonDocument(data->currentItem()->data(Qt::UserRole).toJsonObject()).toJson(QJsonDocument::Indented)));stack->setCurrentIndex(2);});button(da,"完整缺口/阈值/原始输入",[=]{readerBack=1;reader->setPlainText(auctionAnalysis::detail(result));stack->setCurrentIndex(2);});auto raw=new QWidget(stack);stack->addWidget(raw);auto r=new QVBoxLayout(raw);button(r,"返回上一子页",[=]{stack->setCurrentIndex(readerBack);});reader=new QPlainTextEdit(raw);reader->setObjectName("auctionAnalysisReader");reader->setReadOnly(true);r->addWidget(reader,1);connect(search,&QLineEdit::textChanged,this,[=]{if(!loading){listPage=0;render();}});connect(section,qOverload<int>(&QComboBox::currentIndexChanged),this,[=](int){if(!loading){dataPage=0;renderData();}});guard([=]{refresh();});}
void guard(std::function<void()> fn){try{fn();}catch(const std::exception&e){status->setText(QString::fromUtf8(e.what()));}}
QString pointSummary(const QJsonObject& r)const{auto n=[&](QString key){auto v=r.value(key);return v.isDouble()?QString::number(v.toDouble(),'g',12):QString("未知");};return "参考价 "+n("auctionReferencePrice")+" · 匹配 "+n("auctionMatchedVolume")+" 股 · 未匹配买/卖 "+n("auctionUnmatchedBuyVolume")+" / "+n("auctionUnmatchedSellVolume")+" 股";}
QString field(const QJsonObject& s,QString key)const{auto value=key=="instrumentId"?s.value(key):s.value("input").toObject().value(key);return value.toString().isEmpty()?QString("未知"):value.toString();}
void refresh(){if(!provider)throw std::runtime_error("宿主未注入竞价快照，不能生成形态");auto candidate=provider();QSet<QString> ids;for(auto v:candidate){auto s=v.toObject();if(s.value("id").toString().isEmpty()||ids.contains(s.value("id").toString()))throw std::runtime_error("快照身份缺失或重复");ids.insert(s.value("id").toString());}snapshots=candidate;loading=true;for(auto i=filters.begin();i!=filters.end();++i){auto prior=i.value()->currentData();QSet<QString> values;for(auto s:snapshots)values.insert(field(s.toObject(),i.key()));auto options=values.values();options.sort();i.value()->clear();i.value()->addItem(i.key()=="instrumentId"?"全部证券":i.key()=="date"?"全部历史日期":"全部阶段","");for(auto value:options)i.value()->addItem(value=="opening"?"开盘":value=="closing"?"收盘":value,value);int index=i.value()->findData(prior);i.value()->setCurrentIndex(index<0?0:index);}loading=false;render();}
void render(){matched={};for(auto v:snapshots){auto s=v.toObject();bool match=true;for(auto i=filters.begin();i!=filters.end();++i){auto selected=i.value()->currentData().toString();if(!selected.isEmpty()&&selected!=field(s,i.key()))match=false;}if(match&&(search->text().isEmpty()||QString::fromUtf8(QJsonDocument(s).toJson(QJsonDocument::Compact)).contains(search->text(),Qt::CaseInsensitive)))matched.append(s);}listPage=qBound(0,listPage,qMax(0,(matched.size()-1)/20));list->clear();for(int i=listPage*20;i<qMin(matched.size(),(listPage+1)*20);i++){auto s=matched[i].toObject();auto row=new QListWidgetItem(s.value("id").toString()+" · "+field(s,"instrumentId")+" · "+field(s,"date")+" · "+field(s,"phase"),list);row->setData(Qt::UserRole,s);}status->setText(QString("共%1次观察 · 匹配%2 · 第%3/%4页").arg(snapshots.size()).arg(matched.size()).arg(listPage+1).arg(qMax(1,(matched.size()+19)/20)));}
void renderData(){QString key=section->currentData().toString();items=key=="rules"?auctionAnalysis::rules():result.value(key).toArray();if(items.isEmpty()&&(key=="pointAudit"||key=="historyAudit")){auto raw=captured.value("input").toObject().value(key=="pointAudit"?"rows":"history").toArray();for(auto v:raw)items.append(QJsonObject{{"original",v},{"reason","契约或当前时刻不足；仅保留原数据，资格未知"}});}dataPage=qBound(0,dataPage,qMax(0,(items.size()-1)/20));data->clear();for(int i=dataPage*20;i<qMin(items.size(),(dataPage+1)*20);i++){auto item=items[i].toObject(),raw=item.value("original").toObject();QString label=item.value("label").toString();if(label.isEmpty())label=raw.value("date").toString()+" "+raw.value("time").toString()+" "+raw.value("clock").toString()+" · "+item.value("reason").toString()+item.value("excludedReason").toString();if(key=="pointAudit")label+=" · "+pointSummary(raw);auto row=new QListWidgetItem(QString::number(i+1)+" · "+label,data);row->setData(Qt::UserRole,item);}prev->setEnabled(dataPage>0);next->setEnabled((dataPage+1)*20<items.size());status->setText(QString("完整记录%1 · 第%2/%3页；普通报价无指示价/虚拟量就保持未知").arg(items.size()).arg(dataPage+1).arg(qMax(1,(items.size()+19)/20)));}
QJsonObject save()const{QJsonObject q;for(auto i=filters.begin();i!=filters.end();++i)q[i.key()]=i.value()->currentData().toString();return {{"filters",q},{"search",search->text()},{"listPage",listPage},{"dataPage",dataPage},{"captured",captured},{"result",result},{"section",section->currentIndex()},{"view",stack->currentIndex()},{"reader",reader->toPlainText()},{"readerBack",readerBack},{"readerScroll",reader->verticalScrollBar()->value()}};}
void restore(const QJsonObject& s){loading=true;search->setText(s.value("search").toString());auto q=s.value("filters").toObject();for(auto i=filters.begin();i!=filters.end();++i){int index=i.value()->findData(q.value(i.key()).toString());i.value()->setCurrentIndex(index<0?0:index);}listPage=qMax(0,s.value("listPage").toInt());captured=s.value("captured").toObject();result=s.value("result").toObject();dataPage=qMax(0,s.value("dataPage").toInt());section->setCurrentIndex(qBound(0,s.value("section").toInt(),3));reader->setPlainText(s.value("reader").toString());readerBack=s.value("readerBack").toInt(1)==0?0:1;loading=false;render();renderData();summary->setText("已恢复本机捕获分析（不是实时更新）\n"+result.value("reason").toString());stack->setCurrentIndex(qBound(0,s.value("view").toInt(),2));QTimer::singleShot(0,this,[=]{reader->verticalScrollBar()->setValue(s.value("readerScroll").toInt());});}
};
}
QWidget* auctionAnalysisPage(QWidget*p,AuctionAnalysisSnapshots s,std::function<void()> reload){return new Page(p,s,reload);}
void auctionAnalysisRefresh(QWidget*w,const QString& note){if(auto p=dynamic_cast<Page*>(w)){p->guard([=]{p->refresh();});p->sourceNote->setText(note);}}
bool auctionAnalysisBack(QWidget*w){auto p=dynamic_cast<Page*>(w);if(!p||p->stack->currentIndex()==0)return false;p->stack->setCurrentIndex(p->stack->currentIndex()==2?p->readerBack:0);return true;}
QJsonObject auctionAnalysisSaveState(QWidget*w){auto p=dynamic_cast<Page*>(w);return p?p->save():QJsonObject{};}
void auctionAnalysisRestoreState(QWidget*w,const QJsonObject&s){if(auto p=dynamic_cast<Page*>(w))p->restore(s);}
